test('AC-004 accepts \\r\\n line endings', () => {
  assert.deepEqual(parseCsv('a,b\r\n1,2\r\n3,4\r\n'), [
    { a: '1', b: '2' },
    { a: '3', b: '4' },
  ]);
});

test('AC-004 a newline at the very end does not add a row', () => {
  assert.deepEqual(parseCsv('a,b\n1,2\n'), [{ a: '1', b: '2' }]);
